insert into kairo.questions (id, subject, topic, subtopic, learning_objective, concepts_tested, difficulty_rating, cognitive_level, estimated_solving_time_sec, reading_load, calculation_load, distractors, source, year, exam_body, stem, options, correct_option, explanation, lifecycle_state, distractor_rationale) values
($q$chemistry_0331$q$, $q$Chemistry$q$, $q$Chemical Combination$q$, $q$Empirical and Molecular Formula$q$, $q$Answer a real JAMB 2002 question on Empirical and Molecular Formula.$q$, $q$[{"conceptId": "mu9d5t", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "B", "explanation": "Molecular formula must show the actual number of atoms in one molecule (C2H4O2), not the reduced ratio \u2014 mixing up 'simplest ratio' with 'actual count' is the core confusion here.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "A structural formula shows bonding arrangement (e.g. CH3-COOH), which CH2O does not convey at all \u2014 this option confuses formula types entirely.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "A general formula applies to an entire homologous series (e.g. CnH2nO2), not to one specific named compound like ethanoic acid.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$The formula CH2O for ethanoic acid is regarded as its$q$, $q$[{"label": "A", "text": "empirical formula", "isCorrect": true}, {"label": "B", "text": "molecular formula", "isCorrect": false}, {"label": "C", "text": "structural formula", "isCorrect": false}, {"label": "D", "text": "general formula", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Ethanoic acid's actual molecular formula is C2H4O2 (CH3COOH) — CH2O is just its simplest whole-number atom ratio, which is exactly what 'empirical formula' means. The molecular formula would show the real atom count (C2H4O2); a structural formula would show how those atoms connect (CH3-COOH); a general formula describes a whole homologous series (like CnH2nO2 for carboxylic acids), not one specific compound.$q$, $q$live$q$, $q$B: Molecular formula must show the actual number of atoms in one molecule (C2H4O2), not the reduced ratio — mixing up 'simplest ratio' with 'actual count' is the core confusion here. C: A structural formula shows bonding arrangement (e.g. CH3-COOH), which CH2O does not convey at all — this option confuses formula types entirely. D: A general formula applies to an entire homologous series (e.g. CnH2nO2), not to one specific named compound like ethanoic acid.$q$),
($q$chemistry_0332$q$, $q$Chemistry$q$, $q$Chemical Combination$q$, $q$The Mole Concept — Atom Counting$q$, $q$Answer a real JAMB 2002 question on The Mole Concept — Atom Counting.$q$, $q$[{"conceptId": "jniec0", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "B", "explanation": "4 mol Cl2 gives 8 mol atoms (2 atoms per molecule) \u2014 close to argon's 7, but still more; missing that argon is monatomic while chlorine is diatomic understates the gap.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "3 mol O3 gives 9 mol atoms, since ozone has 3 atoms per molecule \u2014 treating moles of gas as directly equal to moles of atoms ignores each gas's atomicity.", "misconceptionId": "missing_prerequisite"}, {"option": "D", "explanation": "1 mol of butane (C4H10) actually gives 14 mol atoms \u2014 far more than 7, since each molecule alone contains 14 atoms; picking the smallest mole number without counting atoms per molecule is the trap.", "misconceptionId": "missing_prerequisite"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$Which of the following gases contains the least number of atoms at s.t.p?$q$, $q$[{"label": "A", "text": "7 moles of argon", "isCorrect": true}, {"label": "B", "text": "4 moles of chlorine", "isCorrect": false}, {"label": "C", "text": "3 moles of ozone", "isCorrect": false}, {"label": "D", "text": "1 mole of butane", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Convert each to total atoms: 7 mol Ar (monatomic) = 7 mol atoms. 4 mol Cl2 (diatomic) = 8 mol atoms. 3 mol O3 (triatomic) = 9 mol atoms. 1 mol C4H10 (14 atoms per molecule) = 14 mol atoms. 7 mol atoms from argon is the smallest of the four.$q$, $q$live$q$, $q$B: 4 mol Cl2 gives 8 mol atoms (2 atoms per molecule) — close to argon's 7, but still more; missing that argon is monatomic while chlorine is diatomic understates the gap. C: 3 mol O3 gives 9 mol atoms, since ozone has 3 atoms per molecule — treating moles of gas as directly equal to moles of atoms ignores each gas's atomicity. D: 1 mol of butane (C4H10) actually gives 14 mol atoms — far more than 7, since each molecule alone contains 14 atoms; picking the smallest mole number without counting atoms per molecule is the trap.$q$),
($q$chemistry_0333$q$, $q$Chemistry$q$, $q$Separation of Mixtures$q$, $q$Separation Techniques$q$, $q$Answer a real JAMB 2002 question on Separation Techniques.$q$, $q$[{"conceptId": "kc1jua", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Components don't need to dissolve in each other at all \u2014 in fact they're being separated because they behave differently, not because they interact with one another.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "Chromatography is a physical separation \u2014 no chemical reaction between component and solvent is required or implied.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "The components are being separated from each other precisely because they do NOT need to react \u2014 assuming a reaction is needed misreads what chromatography actually relies on.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$The chromatographic separation of ink is based on the ability of the components to$q$, $q$[{"label": "A", "text": "dissolve in each other in the column", "isCorrect": false}, {"label": "B", "text": "move at different speeds in the column", "isCorrect": true}, {"label": "C", "text": "react with the solvent", "isCorrect": false}, {"label": "D", "text": "react with each other", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Chromatography separates a mixture because its components have different affinities for the stationary phase versus the mobile phase, so they travel at different speeds through the medium — components that cling less to the paper/column move faster and separate out from those that cling more.$q$, $q$live$q$, $q$A: Components don't need to dissolve in each other at all — in fact they're being separated because they behave differently, not because they interact with one another. C: Chromatography is a physical separation — no chemical reaction between component and solvent is required or implied. D: The components are being separated from each other precisely because they do NOT need to react — assuming a reaction is needed misreads what chromatography actually relies on.$q$),
($q$chemistry_0334$q$, $q$Chemistry$q$, $q$Chemical Combination$q$, $q$Empirical and Molecular Formula$q$, $q$Answer a real JAMB 2002 question on Empirical and Molecular Formula.$q$, $q$[{"conceptId": "mu9d5t", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 84, $q$low$q$, $q$moderate$q$, $q$[{"option": "A", "explanation": "KClO would only account for one oxygen \u2014 dividing the given percentages by atomic mass clearly gives an O:K ratio near 3:1, not 1:1, so this undercounts oxygen.", "misconceptionId": "arithmetic_slip"}, {"option": "B", "explanation": "KClO2 assumes 2 oxygens, but the mole ratio worked out from the percentages (\u22482.45 mol O per \u22480.82 mol K and Cl) rounds to 3, not 2 \u2014 an arithmetic shortfall in the division step.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "KClO4 overshoots \u2014 that would require an oxygen mole ratio of 4, but the computed ratio from the given percentages is closer to 3.", "misconceptionId": "arithmetic_slip"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$A compound contains 31.91% potassium, 28.93% chlorine and the rest oxygen. What is the chemical formula of the compound?$q$, $q$[{"label": "A", "text": "KClO", "isCorrect": false}, {"label": "B", "text": "KClO2", "isCorrect": false}, {"label": "C", "text": "KClO3", "isCorrect": true}, {"label": "D", "text": "KClO4", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Oxygen % = 100 − 31.91 − 28.93 = 39.16%. Divide each by molar mass: K = 31.91/39 = 0.818; Cl = 28.93/35.5 = 0.815; O = 39.16/16 = 2.448. Dividing through by the smallest (0.815) gives a ratio of about 1 : 1 : 3, so the formula is KClO3.$q$, $q$live$q$, $q$A: KClO would only account for one oxygen — dividing the given percentages by atomic mass clearly gives an O:K ratio near 3:1, not 1:1, so this undercounts oxygen. B: KClO2 assumes 2 oxygens, but the mole ratio worked out from the percentages (≈2.45 mol O per ≈0.82 mol K and Cl) rounds to 3, not 2 — an arithmetic shortfall in the division step. D: KClO4 overshoots — that would require an oxygen mole ratio of 4, but the computed ratio from the given percentages is closer to 3.$q$),
($q$chemistry_0335$q$, $q$Chemistry$q$, $q$Nature of Matter$q$, $q$Boiling Point and Purity$q$, $q$Answer a real JAMB 2002 question on Boiling Point and Purity.$q$, $q$[{"conceptId": "bpogj3", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This range is too wide and drags the estimate down toward trichloromethane's 60\u00b0C, ignoring that trichloromethane is only a minor component \u2014 the bulk ethanol should dominate the boiling behaviour.", "misconceptionId": "overgeneralized_rule"}, {"option": "B", "explanation": "This underestimates where the boiling point actually settles \u2014 with ethanol as the overwhelming majority component, the depression from a small impurity shouldn't pull the boiling point down this far.", "misconceptionId": "overgeneralized_rule"}, {"option": "D", "explanation": "Adding a lower-boiling substance to a solvent cannot raise the boiling point above the pure solvent's own boiling point \u2014 this option has the direction of the boiling-point shift backwards.", "misconceptionId": "overgeneralized_rule"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$A little quantity of trichloromethane (b.pt. 60°C) was added to a large quantity of ethanol (b.pt. 78°C). The most probable boiling point of the resultant mixture is from$q$, $q$[{"label": "A", "text": "60\u00b0C \u2013 78\u00b0C", "isCorrect": false}, {"label": "B", "text": "69\u00b0C \u2013 70\u00b0C", "isCorrect": false}, {"label": "C", "text": "70\u00b0C \u2013 74\u00b0C", "isCorrect": true}, {"label": "D", "text": "82\u00b0C \u2013 84\u00b0C", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Since ethanol is present in large excess, the mixture's boiling behaviour stays dominated by ethanol (78°C), only mildly depressed by the small amount of lower-boiling trichloromethane mixed in — so the boiling point sits just below pure ethanol's, in the 70°C–74°C range, rather than dropping all the way toward trichloromethane's 60°C or rising above ethanol's own boiling point.$q$, $q$live$q$, $q$A: This range is too wide and drags the estimate down toward trichloromethane's 60°C, ignoring that trichloromethane is only a minor component — the bulk ethanol should dominate the boiling behaviour. B: This underestimates where the boiling point actually settles — with ethanol as the overwhelming majority component, the depression from a small impurity shouldn't pull the boiling point down this far. D: Adding a lower-boiling substance to a solvent cannot raise the boiling point above the pure solvent's own boiling point — this option has the direction of the boiling-point shift backwards.$q$),
($q$chemistry_0336$q$, $q$Chemistry$q$, $q$Non-Metals & Their Compounds$q$, $q$Nitrogen Compounds — Brown Ring Test$q$, $q$Answer a real JAMB 2002 question on Nitrogen Compounds — Brown Ring Test.$q$, $q$[{"conceptId": "bqhgcv", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "CO has no role in the brown ring test at all \u2014 it's not a nitrogen oxide and can't form the iron-nitrosyl complex responsible for the brown ring.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "CO2 is colourless and chemically unrelated to the nitrate test \u2014 confusing it with NO likely comes from associating 'oxide of carbon' generically with test-tube gas reactions.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "NO2 is a brown gas itself, which makes it an easy but incorrect guess here \u2014 the brown ring test specifically depends on NO forming a brown complex with Fe2+, not on NO2's own colour.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$The gas that gives brown colouration in brown ring test is$q$, $q$[{"label": "A", "text": "CO", "isCorrect": false}, {"label": "B", "text": "NO", "isCorrect": true}, {"label": "C", "text": "CO2", "isCorrect": false}, {"label": "D", "text": "NO2", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$The brown ring test for nitrates works because NO gas, released when a nitrate is treated with dilute acid and reduced by Fe2+, combines with excess Fe2+ ions to form the brown complex [Fe(NO)(H2O)5]2+ at the interface between the two liquid layers — it is specifically NO, not NO2, that forms this complex.$q$, $q$live$q$, $q$A: CO has no role in the brown ring test at all — it's not a nitrogen oxide and can't form the iron-nitrosyl complex responsible for the brown ring. C: CO2 is colourless and chemically unrelated to the nitrate test — confusing it with NO likely comes from associating 'oxide of carbon' generically with test-tube gas reactions. D: NO2 is a brown gas itself, which makes it an easy but incorrect guess here — the brown ring test specifically depends on NO forming a brown complex with Fe2+, not on NO2's own colour.$q$),
($q$chemistry_0337$q$, $q$Chemistry$q$, $q$Metals & Their Compounds$q$, $q$Reactions of Metal Salts with Bases$q$, $q$Answer a real JAMB 2002 question on Reactions of Metal Salts with Bases.$q$, $q$[{"conceptId": "vk5zmy", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "NH4Cl with NaOH liberates ammonia gas (especially on warming) rather than forming a solid \u2014 a gas-forming reaction is not the same as a precipitation reaction.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Na2CO3 is already a soluble sodium salt; mixing it with NaOH (also containing Na+) doesn't produce any new insoluble compound.", "misconceptionId": "missing_prerequisite"}, {"option": "D", "explanation": "CH3COONa is also a soluble sodium salt \u2014 like Na2CO3, there's no metal cation present that would form an insoluble hydroxide with NaOH.", "misconceptionId": "missing_prerequisite"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$Which of the following gives a precipitate when treated with NaOH solution?$q$, $q$[{"label": "A", "text": "NH4Cl", "isCorrect": false}, {"label": "B", "text": "Na2CO3", "isCorrect": false}, {"label": "C", "text": "AlCl3", "isCorrect": true}, {"label": "D", "text": "CH3COONa", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$AlCl3 reacts with NaOH to form a white gelatinous precipitate of Al(OH)3. NH4Cl with NaOH releases ammonia gas on warming but forms no precipitate. Na2CO3 and CH3COONa are both already soluble sodium salts that simply stay in solution with NaOH — no new insoluble product forms.$q$, $q$live$q$, $q$A: NH4Cl with NaOH liberates ammonia gas (especially on warming) rather than forming a solid — a gas-forming reaction is not the same as a precipitation reaction. B: Na2CO3 is already a soluble sodium salt; mixing it with NaOH (also containing Na+) doesn't produce any new insoluble compound. D: CH3COONa is also a soluble sodium salt — like Na2CO3, there's no metal cation present that would form an insoluble hydroxide with NaOH.$q$),
($q$chemistry_0338$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Alkenes — Addition Reactions$q$, $q$Answer a real JAMB 2002 question on Alkenes — Addition Reactions.$q$, $q$[{"conceptId": "ace3du", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "'Nucleophilic' describes a type of attacking species or mechanism step, not the overall reaction category \u2014 hydrogenation is classified by what happens to the molecule (addition), not by this label.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "Substitution reactions replace one atom/group with another; hydrogenation doesn't replace anything \u2014 it adds atoms across the double bond while keeping everything already present.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Oxidation involves loss of electrons or gain of oxygen; hydrogenation is the opposite in spirit \u2014 hydrogen is being gained, which is a reduction, not oxidation, and more specifically it's an addition.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$The reaction of an alkene with hydrogen in the presence of a catalyst is$q$, $q$[{"label": "A", "text": "a nucleophilic reaction", "isCorrect": false}, {"label": "B", "text": "an addition reaction", "isCorrect": true}, {"label": "C", "text": "a substitution reaction", "isCorrect": false}, {"label": "D", "text": "an oxidative reaction", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Hydrogenation of an alkene breaks the C=C pi bond and adds one hydrogen atom to each carbon, with nothing leaving the molecule — the defining feature of an addition reaction, catalysed typically by nickel or platinum.$q$, $q$live$q$, $q$A: 'Nucleophilic' describes a type of attacking species or mechanism step, not the overall reaction category — hydrogenation is classified by what happens to the molecule (addition), not by this label. C: Substitution reactions replace one atom/group with another; hydrogenation doesn't replace anything — it adds atoms across the double bond while keeping everything already present. D: Oxidation involves loss of electrons or gain of oxygen; hydrogenation is the opposite in spirit — hydrogen is being gained, which is a reduction, not oxidation, and more specifically it's an addition.$q$),
($q$chemistry_0339$q$, $q$Chemistry$q$, $q$Non-Metals & Their Compounds$q$, $q$Sulphur Compounds$q$, $q$Answer a real JAMB 2002 question on Sulphur Compounds.$q$, $q$[{"conceptId": "2eamtt", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Sulphate (SO4^2-) doesn't release any gas when treated with cold dilute acid \u2014 there's no volatile product here to carry through to the dichromate test at all.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "NO3- reacting with dilute (not concentrated) HNO3 doesn't generate a reducing gas under these cold, dilute conditions \u2014 the nitrate ion itself isn't the source of a gas here.", "misconceptionId": "missing_prerequisite"}, {"option": "D", "explanation": "Chloride would release HCl gas with the acid, but HCl is not a reducing agent and would not turn acidified dichromate green \u2014 this option confuses 'gas released' with 'gas that reduces dichromate'.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$A rock sample was added to cold dilute HNO3. The gas evolved was passed into a solution of acidified K2Cr2O7 and the solution turned green. The rock sample contains$q$, $q$[{"label": "A", "text": "SO4 2-", "isCorrect": false}, {"label": "B", "text": "SO3 2-", "isCorrect": true}, {"label": "C", "text": "NO3-", "isCorrect": false}, {"label": "D", "text": "Cl-", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Acidified potassium dichromate(VI) is an oxidising agent that turns from orange to green when it is reduced (Cr2O7^2- → Cr3+). Only a reducing gas can cause that colour change, and SO2 — released when dilute acid reacts with a sulphite (SO3^2-) — is exactly such a reducing gas. Sulphate (SO4^2-) releases no gas with dilute acid, nitrate needs concentrated acid or specific conditions to give a reducing gas, and chloride released as HCl gas is not a reducing agent toward dichromate.$q$, $q$live$q$, $q$A: Sulphate (SO4^2-) doesn't release any gas when treated with cold dilute acid — there's no volatile product here to carry through to the dichromate test at all. C: NO3- reacting with dilute (not concentrated) HNO3 doesn't generate a reducing gas under these cold, dilute conditions — the nitrate ion itself isn't the source of a gas here. D: Chloride would release HCl gas with the acid, but HCl is not a reducing agent and would not turn acidified dichromate green — this option confuses 'gas released' with 'gas that reduces dichromate'.$q$),
($q$chemistry_0340$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Oxidation of Alcohols$q$, $q$Answer a real JAMB 2002 question on Oxidation of Alcohols.$q$, $q$[{"conceptId": "4f68ue", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Methanal is the aldehyde from methanol (C1), not ethanol (C2) \u2014 this mixes up which alcohol's oxidation series is being asked about.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Propanal has three carbons, which would only arise from propan-1-ol, not from ethanol \u2014 oxidation never changes the carbon skeleton length.", "misconceptionId": "missing_prerequisite"}, {"option": "D", "explanation": "Butanal has four carbons, from butan-1-ol \u2014 far removed from ethanol's two-carbon chain; oxidation of an alcohol cannot change how many carbons are in the molecule.", "misconceptionId": "missing_prerequisite"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$The intermediate product formed when ethanol is progressively oxidized to ethanoic acid with potassium heptaoxodichromate (VI) is$q$, $q$[{"label": "A", "text": "methanal", "isCorrect": false}, {"label": "B", "text": "propanal", "isCorrect": false}, {"label": "C", "text": "ethanal", "isCorrect": true}, {"label": "D", "text": "butanal", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Oxidation of a primary alcohol proceeds in two stages: alcohol → aldehyde → carboxylic acid, with each stage keeping the same carbon count. Ethanol (C2) is first oxidised to ethanal (C2 aldehyde) and then further to ethanoic acid (C2 acid) — the intermediate must have the same number of carbons as the starting alcohol.$q$, $q$live$q$, $q$A: Methanal is the aldehyde from methanol (C1), not ethanol (C2) — this mixes up which alcohol's oxidation series is being asked about. B: Propanal has three carbons, which would only arise from propan-1-ol, not from ethanol — oxidation never changes the carbon skeleton length. D: Butanal has four carbons, from butan-1-ol — far removed from ethanol's two-carbon chain; oxidation of an alcohol cannot change how many carbons are in the molecule.$q$),
($q$chemistry_0341$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Classification of Alkanols$q$, $q$Answer a real JAMB 2002 question on Classification of Alkanols.$q$, $q$[{"conceptId": "xn8nji", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "A primary alkanol has its OH-carbon attached to only one other carbon (or none) \u2014 here the OH-carbon is flanked by two separate carbon groups, which rules out 'primary'.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "A tertiary alkanol has its OH-carbon attached to three other carbon groups with no H on that carbon \u2014 here there's still one H directly on the OH-bearing carbon, so it can't be tertiary.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "A glycol (diol) has two separate -OH groups on the molecule \u2014 this structure has only one -OH, so it's a simple alkanol, not a diol.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$CH3-CH(OH)-CH2-CH3 — the compound above is a$q$, $q$[{"label": "A", "text": "primary alkanol", "isCorrect": false}, {"label": "B", "text": "secondary alkanol", "isCorrect": true}, {"label": "C", "text": "tertiary alkanol", "isCorrect": false}, {"label": "D", "text": "glycol", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$The carbon bearing the -OH group is attached to two other carbon groups (a CH3 on one side and a CH2CH3 on the other) plus one hydrogen — that pattern, OH-carbon bonded to exactly two carbon chains, defines a secondary alcohol (this is butan-2-ol).$q$, $q$live$q$, $q$A: A primary alkanol has its OH-carbon attached to only one other carbon (or none) — here the OH-carbon is flanked by two separate carbon groups, which rules out 'primary'. C: A tertiary alkanol has its OH-carbon attached to three other carbon groups with no H on that carbon — here there's still one H directly on the OH-bearing carbon, so it can't be tertiary. D: A glycol (diol) has two separate -OH groups on the molecule — this structure has only one -OH, so it's a simple alkanol, not a diol.$q$),
($q$chemistry_0342$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Alkynes — Terminal Alkyne Test$q$, $q$Answer a real JAMB 2002 question on Alkynes — Terminal Alkyne Test.$q$, $q$[{"conceptId": "vfpcni", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "But-2-yne does have a C\u2261C triple bond, but it's internal \u2014 both triple-bonded carbons carry a CH3 group instead of a hydrogen, so there's no acidic \u2261C-H for copper to replace.", "misconceptionId": "missing_prerequisite"}, {"option": "C", "explanation": "But-1-ene only has a C=C double bond, not a triple bond \u2014 the copper(I) acetylide test is specific to terminal alkynes, and an alkene simply doesn't have the right functional group to react this way.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Butane is fully saturated with no double or triple bonds at all, so there is no pi system or acetylenic hydrogen for the copper reagent to interact with.", "misconceptionId": "missing_prerequisite"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$A red precipitate of copper(I) carbide (acetylide) is formed when ammoniacal copper(I) chloride solution is introduced into$q$, $q$[{"label": "A", "text": "CH3-C\u2261C-CH3 (but-2-yne)", "isCorrect": false}, {"label": "B", "text": "CH3-CH2-C\u2261CH (but-1-yne)", "isCorrect": true}, {"label": "C", "text": "CH2=CH-CH2-CH3 (but-1-ene)", "isCorrect": false}, {"label": "D", "text": "CH3-CH2-CH2-CH3 (butane)", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Ammoniacal copper(I) chloride only gives a red precipitate with terminal alkynes — those with a hydrogen directly on a triple-bonded carbon (≡C-H), because that acidic hydrogen is replaced by copper to form the acetylide. But-2-yne has its triple bond in the middle with no acetylenic H, but-1-yne has a terminal ≡C-H, but-1-ene is an alkene (no triple bond at all), and butane is a saturated alkane with no multiple bond whatsoever.$q$, $q$live$q$, $q$A: But-2-yne does have a C≡C triple bond, but it's internal — both triple-bonded carbons carry a CH3 group instead of a hydrogen, so there's no acidic ≡C-H for copper to replace. C: But-1-ene only has a C=C double bond, not a triple bond — the copper(I) acetylide test is specific to terminal alkynes, and an alkene simply doesn't have the right functional group to react this way. D: Butane is fully saturated with no double or triple bonds at all, so there is no pi system or acetylenic hydrogen for the copper reagent to interact with.$q$),
($q$chemistry_0343$q$, $q$Chemistry$q$, $q$Chemistry & Industry$q$, $q$Haber Process and Uses of Hydrogen$q$, $q$Answer a real JAMB 2002 question on Haber Process and Uses of Hydrogen.$q$, $q$[{"conceptId": "k2zkym", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Methyl alcohol (methanol) is industrially produced from hydrogen and carbon monoxide, but this is a smaller-scale use than ammonia synthesis.", "misconceptionId": "overgeneralized_rule"}, {"option": "B", "explanation": "Ethyl alcohol production is mainly via fermentation, not primarily a hydrogen-consuming industrial process \u2014 hydrogen isn't the defining input here at all.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "Hydrogenation of oils (e.g. making margarine) is a real use of hydrogen, but it's a minor consumer compared to the massive scale of ammonia manufacture.", "misconceptionId": "overgeneralized_rule"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$The most important use of hydrogen is in the$q$, $q$[{"label": "A", "text": "manufacture of methyl alcohol", "isCorrect": false}, {"label": "B", "text": "manufacture of ethyl alcohol", "isCorrect": false}, {"label": "C", "text": "hydrogenation of oils", "isCorrect": false}, {"label": "D", "text": "manufacture of ammonia", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$Hydrogen's single largest industrial use is the Haber process, combining it with nitrogen from the air to manufacture ammonia (N2 + 3H2 → 2NH3) — the foundation of the world's nitrogen fertiliser supply, which dwarfs hydrogen's other uses in scale.$q$, $q$live$q$, $q$A: Methyl alcohol (methanol) is industrially produced from hydrogen and carbon monoxide, but this is a smaller-scale use than ammonia synthesis. B: Ethyl alcohol production is mainly via fermentation, not primarily a hydrogen-consuming industrial process — hydrogen isn't the defining input here at all. C: Hydrogenation of oils (e.g. making margarine) is a real use of hydrogen, but it's a minor consumer compared to the massive scale of ammonia manufacture.$q$),
($q$chemistry_0344$q$, $q$Chemistry$q$, $q$Chemistry & Industry$q$, $q$Polymers and Their Uses$q$, $q$Answer a real JAMB 2002 question on Polymers and Their Uses.$q$, $q$[{"conceptId": "x5x9l4", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "B", "explanation": "Polystyrene is used for rigid packaging and thermal (not electrical) insulation in foam form \u2014 it doesn't match the specific packaging-plus-electrical-insulation combination as precisely as polyethene.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Polyamide (nylon) is primarily known for fibres and textiles, not for packaging film or electrical cable insulation \u2014 its main applications lie elsewhere.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Polycarbonate is valued for strength and optical clarity (used in lenses, discs, bulletproof glass), not as a general-purpose packaging or wire-insulation material.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$Which of the following polymers is suitable for packaging and electrical insulation?$q$, $q$[{"label": "A", "text": "Polyethene", "isCorrect": true}, {"label": "B", "text": "Polystyrene", "isCorrect": false}, {"label": "C", "text": "Polyamide", "isCorrect": false}, {"label": "D", "text": "Polycarbonate", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Polyethene (polythene) is flexible, chemically inert, waterproof, and a good electrical insulator, making it the standard material for plastic packaging (bags, film, containers) and cable/wire insulation. Polystyrene is more associated with rigid/foam packaging and insulation panels rather than electrical wire insulation; polyamide (nylon) is mainly a textile/fibre polymer; polycarbonate is prized for impact-resistant transparency (e.g. lenses, CDs) rather than as a general packaging/insulation material.$q$, $q$live$q$, $q$B: Polystyrene is used for rigid packaging and thermal (not electrical) insulation in foam form — it doesn't match the specific packaging-plus-electrical-insulation combination as precisely as polyethene. C: Polyamide (nylon) is primarily known for fibres and textiles, not for packaging film or electrical cable insulation — its main applications lie elsewhere. D: Polycarbonate is valued for strength and optical clarity (used in lenses, discs, bulletproof glass), not as a general-purpose packaging or wire-insulation material.$q$),
($q$chemistry_0345$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Alkanols and Soap Chemistry (Saponification)$q$, $q$Answer a real JAMB 2002 question on Alkanols and Soap Chemistry (Saponification).$q$, $q$[{"conceptId": "z9kmjm", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Acidification means adding acid to a solution \u2014 this process uses a base (caustic soda), the opposite of what 'acidification' implies.", "misconceptionId": "misunderstood_terminology"}, {"option": "B", "explanation": "Hydrolysis is the general term for breaking a bond using water, and it IS technically occurring here, but the specific named process for fat + alkali is the more precise term 'saponification' \u2014 the general term isn't the best answer when a specific one exists for this exact reaction.", "misconceptionId": "overgeneralized_rule"}, {"option": "D", "explanation": "Esterification is the reverse process \u2014 combining an alcohol and acid to FORM an ester \u2014 not breaking one down, which is the opposite of what's described.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$The boiling of fat and aqueous caustic soda is referred to as$q$, $q$[{"label": "A", "text": "acidification", "isCorrect": false}, {"label": "B", "text": "hydrolysis", "isCorrect": false}, {"label": "C", "text": "saponification", "isCorrect": true}, {"label": "D", "text": "esterification", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Boiling a fat (an ester of glycerol and fatty acids) with concentrated aqueous NaOH is specifically called saponification — it hydrolyses the ester bonds under basic conditions to produce soap (sodium salts of fatty acids) and glycerol. 'Hydrolysis' is the broader chemical process happening, but the named process for fat + alkali specifically is saponification.$q$, $q$live$q$, $q$A: Acidification means adding acid to a solution — this process uses a base (caustic soda), the opposite of what 'acidification' implies. B: Hydrolysis is the general term for breaking a bond using water, and it IS technically occurring here, but the specific named process for fat + alkali is the more precise term 'saponification' — the general term isn't the best answer when a specific one exists for this exact reaction. D: Esterification is the reverse process — combining an alcohol and acid to FORM an ester — not breaking one down, which is the opposite of what's described.$q$),
($q$chemistry_0346$q$, $q$Chemistry$q$, $q$Chemistry & Industry$q$, $q$Glass Manufacture$q$, $q$Answer a real JAMB 2002 question on Glass Manufacture.$q$, $q$[{"conceptId": "bv73sr", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Sodium hydrogencarbonate is not the raw material used in glassmaking \u2014 the industrial process specifically uses the carbonate (soda ash), not the bicarbonate.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Potassium sulphate isn't part of the standard soda-lime glass recipe \u2014 this substitutes the wrong alkali-metal compound entirely.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Potassium carbonate is used for specialty glasses (like some optical or borosilicate-type glass), not for ordinary soda-lime glass, which specifically uses the sodium salt.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$Ordinary glass is manufactured from silica, CaCO3 and$q$, $q$[{"label": "A", "text": "NaHCO3", "isCorrect": false}, {"label": "B", "text": "K2SO4", "isCorrect": false}, {"label": "C", "text": "K2CO3", "isCorrect": false}, {"label": "D", "text": "Na2CO3", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$Ordinary soda-lime glass is made by fusing silica (sand, SiO2), limestone (CaCO3) and sodium carbonate (Na2CO3, 'soda ash') — the sodium carbonate lowers the melting point of silica, making large-scale glass production economical.$q$, $q$live$q$, $q$A: Sodium hydrogencarbonate is not the raw material used in glassmaking — the industrial process specifically uses the carbonate (soda ash), not the bicarbonate. B: Potassium sulphate isn't part of the standard soda-lime glass recipe — this substitutes the wrong alkali-metal compound entirely. C: Potassium carbonate is used for specialty glasses (like some optical or borosilicate-type glass), not for ordinary soda-lime glass, which specifically uses the sodium salt.$q$),
($q$chemistry_0347$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Isomerism$q$, $q$Answer a real JAMB 2002 question on Isomerism.$q$, $q$[{"conceptId": "j32bof", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "2 accounts for only n-hexane and one methylpentane, missing the remaining branched isomers \u2014 a significant undercount.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "3 catches the straight chain and the two methylpentane isomers, but still misses both dimethylbutane isomers.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "4 is close but still misses one of the five total isomers \u2014 a common near-miss when isomer-counting by memory rather than systematically drawing every branching arrangement.", "misconceptionId": "formula_recall_error"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$The number of isomers formed by C6H14 is$q$, $q$[{"label": "A", "text": "2", "isCorrect": false}, {"label": "B", "text": "3", "isCorrect": false}, {"label": "C", "text": "4", "isCorrect": false}, {"label": "D", "text": "5", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$C6H14 (hexane) has five structural isomers: n-hexane, 2-methylpentane, 3-methylpentane, 2,2-dimethylbutane, and 2,3-dimethylbutane.$q$, $q$live$q$, $q$A: 2 accounts for only n-hexane and one methylpentane, missing the remaining branched isomers — a significant undercount. B: 3 catches the straight chain and the two methylpentane isomers, but still misses both dimethylbutane isomers. C: 4 is close but still misses one of the five total isomers — a common near-miss when isomer-counting by memory rather than systematically drawing every branching arrangement.$q$),
($q$chemistry_0348$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Polymers and Macromolecules — Synthetic vs Natural$q$, $q$Answer a real JAMB 2002 question on Polymers and Macromolecules — Synthetic vs Natural.$q$, $q$[{"conceptId": "lteab6", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "B", "explanation": "This mixes a synthetic polymer (nylon) with a natural one (keratin) in the same 'synthetic' grouping, and does the same on the other side \u2014 the pairing doesn't sort them correctly by origin.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "This swaps the categories entirely \u2014 polyethylene (synthetic) is grouped with keratin (natural), and nylon (synthetic) is grouped with haemoglobin (natural), mixing both groups.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "This pairs haemoglobin (natural) with nylon (synthetic) together, and keratin (natural) with polyethylene (synthetic) together \u2014 every pairing here crosses the synthetic/natural boundary.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$Which of these pairs are synthetic and natural macromolecules respectively?$q$, $q$[{"label": "A", "text": "Nylon and polyethylene, keratin and haemoglobin", "isCorrect": true}, {"label": "B", "text": "Nylon and keratin, polyethylene and haemoglobin", "isCorrect": false}, {"label": "C", "text": "Polyethylene and keratin, nylon and haemoglobin", "isCorrect": false}, {"label": "D", "text": "Haemoglobin and nylon, keratin and polyethylene", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Nylon and polyethylene are both man-made (synthetic) polymers, while keratin (in hair/nails) and haemoglobin (in blood) are both naturally occurring biological macromolecules — so the correct pairing keeps all synthetic examples together and all natural examples together.$q$, $q$live$q$, $q$B: This mixes a synthetic polymer (nylon) with a natural one (keratin) in the same 'synthetic' grouping, and does the same on the other side — the pairing doesn't sort them correctly by origin. C: This swaps the categories entirely — polyethylene (synthetic) is grouped with keratin (natural), and nylon (synthetic) is grouped with haemoglobin (natural), mixing both groups. D: This pairs haemoglobin (natural) with nylon (synthetic) together, and keratin (natural) with polyethylene (synthetic) together — every pairing here crosses the synthetic/natural boundary.$q$),
($q$chemistry_0349$q$, $q$Chemistry$q$, $q$Nature of Matter$q$, $q$Catenation$q$, $q$Answer a real JAMB 2002 question on Catenation.$q$, $q$[{"conceptId": "mhljhv", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Nitrogen can form some N-N bonded species, but only very short and unstable ones (like hydrazine, N2H4) \u2014 nothing close to carbon's extensive chain-forming ability that defines catenation as a defining property.", "misconceptionId": "overgeneralized_rule"}, {"option": "B", "explanation": "Chlorine atoms don't form long self-bonded chains under normal conditions \u2014 this option confuses general reactivity with the specific ability to catenate.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "Bromine, like chlorine, exists as simple diatomic molecules (Br2) and doesn't catenate into longer chains \u2014 this again conflates 'being an element' with 'being able to self-link extensively'.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$An example of an element that can catenate is$q$, $q$[{"label": "A", "text": "nitrogen", "isCorrect": false}, {"label": "B", "text": "chlorine", "isCorrect": false}, {"label": "C", "text": "carbon", "isCorrect": true}, {"label": "D", "text": "bromine", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Catenation is the ability of atoms of the same element to bond to each other in long chains or rings. Carbon does this extensively (the basis of all organic chemistry), far more than nitrogen, chlorine, or bromine, which form at most very short chains under special conditions.$q$, $q$live$q$, $q$A: Nitrogen can form some N-N bonded species, but only very short and unstable ones (like hydrazine, N2H4) — nothing close to carbon's extensive chain-forming ability that defines catenation as a defining property. B: Chlorine atoms don't form long self-bonded chains under normal conditions — this option confuses general reactivity with the specific ability to catenate. D: Bromine, like chlorine, exists as simple diatomic molecules (Br2) and doesn't catenate into longer chains — this again conflates 'being an element' with 'being able to self-link extensively'.$q$),
($q$chemistry_0350$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Fermentation and Distillation$q$, $q$Answer a real JAMB 2002 question on Fermentation and Distillation.$q$, $q$[{"conceptId": "kk9o6y", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Distillation alone doesn't produce ethanol \u2014 distillation only separates/purifies substances already present; ethanol has to be biologically generated first through fermentation, not through distillation itself.", "misconceptionId": "misunderstood_terminology"}, {"option": "B", "explanation": "Catalytic oxidation of methane doesn't yield ethanol as a product \u2014 this confuses a real industrial process (used for other purposes) with the actual established route to ethanol.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Destructive distillation of wood is the classic source of methanol ('wood alcohol'), not ethanol \u2014 mixing up which alcohol comes from which traditional process is the key error here.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$Ethanol can easily be produced by$q$, $q$[{"label": "A", "text": "distillation of starch solution", "isCorrect": false}, {"label": "B", "text": "catalytic oxidation of methane", "isCorrect": false}, {"label": "C", "text": "destructive distillation of wood", "isCorrect": false}, {"label": "D", "text": "fermentation of starch", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$The classic method of ethanol production is fermentation of starch/sugar solutions using yeast enzymes (starch is first hydrolysed to glucose, then fermented to ethanol and CO2) — this is the standard method taught and used industrially/traditionally.$q$, $q$live$q$, $q$A: Distillation alone doesn't produce ethanol — distillation only separates/purifies substances already present; ethanol has to be biologically generated first through fermentation, not through distillation itself. B: Catalytic oxidation of methane doesn't yield ethanol as a product — this confuses a real industrial process (used for other purposes) with the actual established route to ethanol. C: Destructive distillation of wood is the classic source of methanol ('wood alcohol'), not ethanol — mixing up which alcohol comes from which traditional process is the key error here.$q$),
($q$chemistry_0351$q$, $q$Chemistry$q$, $q$Metals & Their Compounds$q$, $q$Reactivity and Electrochemical Series$q$, $q$Answer a real JAMB 2002 question on Reactivity and Electrochemical Series.$q$, $q$[{"conceptId": "e6wz62", "weight": 1}]$q$::jsonb, 1, $q$application$q$, 45, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Silver is well below hydrogen in the reactivity series and simply does not react with dilute hydrochloric acid \u2014 no displacement, no gas.", "misconceptionId": "missing_prerequisite"}, {"option": "B", "explanation": "Gold is one of the least reactive metals of all, sitting far below hydrogen in the reactivity series \u2014 it is essentially inert toward dilute acids.", "misconceptionId": "missing_prerequisite"}, {"option": "C", "explanation": "Copper, though a common metal in reactivity-series questions, is also below hydrogen and does not displace it from dilute acids \u2014 a frequent point of confusion since copper does react with other reagents (like concentrated acids) under different conditions.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$Hydrogen is readily released when dilute hydrochloric acid reacts with$q$, $q$[{"label": "A", "text": "Ag", "isCorrect": false}, {"label": "B", "text": "Au", "isCorrect": false}, {"label": "C", "text": "Cu", "isCorrect": false}, {"label": "D", "text": "Na", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$Only metals above hydrogen in the reactivity series displace it from dilute acids. Sodium is far more reactive than hydrogen and reacts vigorously with dilute HCl (and even with water) to release hydrogen gas. Silver, gold, and copper are all below hydrogen in reactivity and do not react with dilute HCl at all.$q$, $q$live$q$, $q$A: Silver is well below hydrogen in the reactivity series and simply does not react with dilute hydrochloric acid — no displacement, no gas. B: Gold is one of the least reactive metals of all, sitting far below hydrogen in the reactivity series — it is essentially inert toward dilute acids. C: Copper, though a common metal in reactivity-series questions, is also below hydrogen and does not displace it from dilute acids — a frequent point of confusion since copper does react with other reagents (like concentrated acids) under different conditions.$q$),
($q$chemistry_0352$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$Subatomic Particles and Ion Charge$q$, $q$Answer a real JAMB 2002 question on Subatomic Particles and Ion Charge.$q$, $q$[{"conceptId": "f4y1pg", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "1.0008 is the proton's mass in atomic mass units (u), not in grams \u2014 this option confuses two different unit systems, giving a numerically similar but dimensionally wrong statement.", "misconceptionId": "unit_conversion_error"}, {"option": "B", "explanation": "It's the electron's mass that's treated as negligible compared to protons and neutrons \u2014 this option has the comparison backwards.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Total proton mass being 'always half' the nuclear mass is only true when protons and neutrons are equal in number, which isn't true for most nuclei \u2014 this overgeneralizes from special cases (like carbon-12) to all nuclei.", "misconceptionId": "overgeneralized_rule"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$Which of the following statements is true of a proton?$q$, $q$[{"label": "A", "text": "The mass of a proton is 1.0008 g", "isCorrect": false}, {"label": "B", "text": "The mass of a proton is negligible", "isCorrect": false}, {"label": "C", "text": "The mass of a proton is about 1840 times the mass of an electron", "isCorrect": true}, {"label": "D", "text": "The total mass of the protons in a particular nucleus is always half the nuclear mass", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$A proton's mass is roughly 1840 times that of an electron — this ratio is the standard fact used to justify why electron mass is ignored in atomic mass calculations. Its actual mass is about 1.67×10^-24 g (not 1.0008 g, which is closer to its mass in atomic mass units, a different unit entirely), and it's the electron whose mass is comparatively negligible, not the proton's.$q$, $q$live$q$, $q$A: 1.0008 is the proton's mass in atomic mass units (u), not in grams — this option confuses two different unit systems, giving a numerically similar but dimensionally wrong statement. B: It's the electron's mass that's treated as negligible compared to protons and neutrons — this option has the comparison backwards. D: Total proton mass being 'always half' the nuclear mass is only true when protons and neutrons are equal in number, which isn't true for most nuclei — this overgeneralizes from special cases (like carbon-12) to all nuclei.$q$),
($q$chemistry_0353$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$Radioactivity and Half-Life$q$, $q$Answer a real JAMB 2002 question on Radioactivity and Half-Life.$q$, $q$[{"conceptId": "ot0voy", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "B", "explanation": "\u00b9\u00b3\u2086C changes the mass number, but beta decay conserves mass number \u2014 only the atomic number should change, not the mass number.", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "\u00b9\u00b2\u2086C changes both the mass number and keeps the same atomic number \u2014 beta decay must increase the atomic number, and it must conserve mass number, so this option gets both quantities wrong.", "misconceptionId": "sign_error"}, {"option": "D", "explanation": "\u00b9\u00b2\u2085B decreases both mass number and atomic number, which matches neither how mass number is conserved nor how atomic number should increase in beta decay \u2014 this looks more like it was derived from an unrelated decay type.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$¹⁴₆C → X + β⁻. In the nuclear equation above, X represents$q$, $q$[{"label": "A", "text": "\u00b9\u2074\u2087N", "isCorrect": true}, {"label": "B", "text": "\u00b9\u00b3\u2086C", "isCorrect": false}, {"label": "C", "text": "\u00b9\u00b2\u2086C", "isCorrect": false}, {"label": "D", "text": "\u00b9\u00b2\u2085B", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$In beta decay, a neutron converts to a proton and an emitted electron (β⁻), so the mass number stays the same (14) while the atomic number increases by 1 (6 → 7). That makes X nitrogen-14 (¹⁴₇N), which balances both mass number (14=14+0) and atomic number (6=7-1) across the equation.$q$, $q$live$q$, $q$B: ¹³₆C changes the mass number, but beta decay conserves mass number — only the atomic number should change, not the mass number. C: ¹²₆C changes both the mass number and keeps the same atomic number — beta decay must increase the atomic number, and it must conserve mass number, so this option gets both quantities wrong. D: ¹²₅B decreases both mass number and atomic number, which matches neither how mass number is conserved nor how atomic number should increase in beta decay — this looks more like it was derived from an unrelated decay type.$q$),
($q$chemistry_0354$q$, $q$Chemistry$q$, $q$Kinetic Theory & Gas Laws$q$, $q$Gas Laws$q$, $q$Answer a real JAMB 2002 question on Gas Laws.$q$, $q$[{"conceptId": "84csd7", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "14 comes from dividing 28 by 2 directly, treating the rate ratio as a simple linear (not square-root) relationship with molar mass \u2014 Graham's law involves a square root, not direct proportion.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "56 comes from multiplying 28 by 2 directly \u2014 again skipping the square-root relationship in Graham's law and treating rate ratio as directly (not inversely-square-root) proportional to mass ratio.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "120 doesn't follow from the correct application of Graham's law at all \u2014 likely from a miscalculated intermediate step rather than correctly squaring the rate ratio.", "misconceptionId": "arithmetic_slip"}]$q$::jsonb, $q$jamb_past_question$q$, 2002, $q$JAMB$q$, $q$A gas X diffuses twice as fast as gas Y under the same condition. If the relative molecular mass of X is 28, calculate the relative molecular mass of Y$q$, $q$[{"label": "A", "text": "14", "isCorrect": false}, {"label": "B", "text": "56", "isCorrect": false}, {"label": "C", "text": "112", "isCorrect": true}, {"label": "D", "text": "120", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Graham's law: rate_X / rate_Y = √(My/Mx). Given rate_X = 2 × rate_Y: 2 = √(My/28), so My/28 = 4, giving My = 112.$q$, $q$live$q$, $q$A: 14 comes from dividing 28 by 2 directly, treating the rate ratio as a simple linear (not square-root) relationship with molar mass — Graham's law involves a square root, not direct proportion. B: 56 comes from multiplying 28 by 2 directly — again skipping the square-root relationship in Graham's law and treating rate ratio as directly (not inversely-square-root) proportional to mass ratio. D: 120 doesn't follow from the correct application of Graham's law at all — likely from a miscalculated intermediate step rather than correctly squaring the rate ratio.$q$),
